<dialog class="page-media-dialog about-media-dialog" id="aboutMediaDialog"><div class="page-media-dialog-head"><div><span class="panel-kicker">مكتبة الوسائط</span><h3>اختيار صورة التعريف</h3></div><button type="button" data-close-about-media aria-label="إغلاق">×</button></div><section><input class="media-dialog-search" type="search" placeholder="ابحث في الصور..." data-about-media-search><div class="page-media-grid"><?php foreach($mediaLibrary as $media):?><button type="button" data-pick-about-media data-path="<?=e($media['path'])?>" data-alt="<?=e($media['alt_text']?:$media['title']?:$media['original_name']?:'')?>"><img src="<?=e($media['path'])?>" alt=""><span><?=e($media['title']?:$media['original_name']?:'صورة')?></span></button><?php endforeach;?></div><div class="actions"><button type="button" class="btn btn-ghost" data-remove-about-media>إزالة الصورة</button><a class="btn btn-ghost" href="/admin/media" target="_blank" rel="noopener">فتح مكتبة الوسائط</a></div></section></dialog>

<script>
(()=>{const form=document.querySelector('[data-about-editor]');if(!form)return;let dirty=false,submitting=false;const state=form.querySelector('[data-save-state]');
 const mark=()=>{dirty=true;if(state)state.hidden=false};form.addEventListener('input',mark);form.addEventListener('change',mark);
 form.querySelectorAll('[data-about-rich]').forEach(editor=>{const key=editor.dataset.aboutRich,target=form.querySelector('[data-about-target="'+key+'"]'),field=editor.closest('.about-rich-field');editor.addEventListener('input',()=>{target.value=editor.innerHTML;mark()});field.querySelectorAll('[data-rich-command]').forEach(button=>button.onclick=()=>{editor.focus();document.execCommand(button.dataset.richCommand,false,button.dataset.value||null);target.value=editor.innerHTML;mark()});field.querySelector('[data-rich-link]').onclick=()=>{const url=prompt('أدخل الرابط الداخلي أو الرابط الكامل:','/');if(url&&/^(https?:\/\/|\/|#|mailto:)/i.test(url)){editor.focus();document.execCommand('createLink',false,url);target.value=editor.innerHTML;mark()}}});
 form.addEventListener('submit',()=>{submitting=true;form.querySelectorAll('[data-about-rich]').forEach(editor=>form.querySelector('[data-about-target="'+editor.dataset.aboutRich+'"]').value=editor.innerHTML)});window.addEventListener('beforeunload',event=>{if(dirty&&!submitting){event.preventDefault();event.returnValue=''}});
 const dialog=document.getElementById('aboutMediaDialog'),input=form.querySelector('[data-about-image]'),preview=form.querySelector('[data-open-about-media]'),alt=form.querySelector('[name="image_alt"]');preview.onclick=()=>dialog.showModal();dialog.querySelector('[data-close-about-media]').onclick=()=>dialog.close();dialog.querySelectorAll('[data-pick-about-media]').forEach(button=>button.onclick=()=>{input.value=button.dataset.path;preview.innerHTML='<img src="'+button.dataset.path+'" alt="">';if(!alt.value)alt.value=button.dataset.alt||'';mark();dialog.close()});dialog.querySelector('[data-remove-about-media]').onclick=()=>{input.value='';preview.innerHTML='<span>اختيار من مكتبة الوسائط</span>';mark();dialog.close()};const search=dialog.querySelector('[data-about-media-search]');search.oninput=()=>{const q=search.value.trim().toLowerCase();dialog.querySelectorAll('[data-pick-about-media]').forEach(button=>button.hidden=q&&!button.textContent.toLowerCase().includes(q))};
})();
</script>
